/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=person, operation=search
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Search deals */
export type PipedriveV2PersonSearchParams = {
  resource: 'person';
  operation: 'search';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * The search term to look for. Minimum 2 characters (or 1 if using exact_match).
 */
    term: string | Expression<string> | PlaceholderValue;
/**
 * Whether only full exact matches against the given term are returned. It is not case sensitive.
 * @default false
 */
    exactMatch?: boolean | Expression<boolean>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 100
 */
    limit?: number | Expression<number>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** Supports including optional fields in the results which are not provided by default. Example: person.picture.
     */
    includeFields?: string | Expression<string> | PlaceholderValue;
    /** Will filter persons by the provided Organization ID
     */
    organizationId?: string | Expression<string> | PlaceholderValue;
    /** A comma-separated string array. The fields to perform the search from. Defaults to all of them.
     * @default ["custom_fields","email","name","notes","phone"]
     */
    fields?: Array<'custom_fields' | 'email' | 'name' | 'notes' | 'phone'>;
  };
};

export type PipedriveV2PersonSearchOutput = {
  custom_fields?: Array<string>;
  emails?: Array<string>;
  id?: number;
  name?: string;
  notes?: Array<string>;
  organization?: {
    id?: number;
    name?: string;
  };
  owner?: {
    id?: number;
  };
  phones?: Array<string>;
  result_score?: number;
  type?: string;
  update_time?: string;
  visible_to?: number;
};

export type PipedriveV2PersonSearchNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2PersonSearchParams>;
  output?: Items<PipedriveV2PersonSearchOutput>;
};